const body = $input.first().json.body;
if (!body || typeof body.eventId !== 'string' || !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(body.eventId) || typeof body.eventType !== 'string') {
  throw new Error('Invalid outbox envelope');
}
const delivered = $getWorkflowStaticData('global');
return [{ json: { body, route: delivered['outbox:' + body.eventId] ? 'duplicate' : 'send' } }];

const body = $('Check Delivery Ledger').first().json.body;
const delivered = $getWorkflowStaticData('global');
const key = 'outbox:' + body.eventId;
delivered[key] = { deliveredAt: new Date().toISOString() };
const keys = Object.keys(delivered).filter((candidate) => candidate.startsWith('outbox:'));
if (keys.length > 10000) {
  keys.sort((a, b) => String(delivered[a]?.deliveredAt || '').localeCompare(String(delivered[b]?.deliveredAt || '')));
  for (const staleKey of keys.slice(0, keys.length - 10000)) delete delivered[staleKey];
}
return [{ json: { body } }];
